let state;try{state=JSON.parse(localStorage.getItem('nihongo-path')||'{}')}catch{state={}}
state={lang:'bn',level:'N5',saved:[],learned:[],dark:false,...state};if(!['bn','en'].includes(state.lang))state.lang='bn';if(!LEVELS.includes(state.level))state.level='N5';for(const k of ['saved','learned'])state[k]=Array.isArray(state[k])?state[k].filter(x=>typeof x==='string'):[];
const routeFile=location.pathname.split('/').pop().toLowerCase(),levelRoute=/^n([1-5])\.html$/.exec(routeFile);let page=levelRoute?'level':({'lessons.html':'lessons','review.html':'review','progress.html':'progress','sources.html':'sources'})[routeFile]||'home';if(levelRoute)state.level='N'+levelRoute[1];let kind=new URLSearchParams(location.search).get('section')||'vocab';if(!KINDS.includes(kind))kind='vocab';let index={},db={},reviewed={},query='',filter='all',limit=30,current=null,mode='flash',cardIndex=0,flipped=false,answered=false;
const t=()=>COPY[state.lang],persist=()=>localStorage.setItem('nihongo-path',JSON.stringify(state)),entryKey=(e,k=kind)=>`${k}:${e.level}:${e.id}`,title=e=>e.word||e.pattern||e.character||'',english=e=>e.meaning||e.meanings?.join('; ')||'',checked=(e,field,k=kind)=>!!reviewed[`${e.level}:${k}:${e.id}:bn:${field}`],local=e=>e.locales?.bn||{},fieldText=(e,field,k=kind)=>state.lang==='bn'&&checked(e,field,k)?local(e)[field]:(field==='meaning'?english(e):field==='guidance'?e.notes||'':e[field]||''),meaning=(e,k=kind)=>fieldText(e,'meaning',k),badge=(e,field='meaning',k=kind)=>state.lang==='bn'?`<span class="review-status ${checked(e,field,k)?'checked':''}" title="${esc(t().ai)}">${esc(checked(e,field,k)?(field==='meaning'?t().checked:t().checkedField):t().pending)}</span>`:'',count=n=>index[n]||{vocab:0,grammar:0,kanji:0,extra_vocab:0};
function paintTheme(){document.body.classList.toggle('dark',!!state.dark);document.documentElement.style.colorScheme=state.dark?'dark':'light'}
function nav(){for(const selector of ['#sideNav','#bottom'])$(selector).innerHTML=['home','lessons','review','progress'].map((p,i)=>`<a class="navitem ${page===p||(p==='lessons'&&page==='level')?'active':''}" href="${p==='home'?'index':p}.html" ${page===p||(p==='lessons'&&page==='level')?'aria-current="page"':''}><span aria-hidden="true">${['⌂','▤','↻','◴'][i]}</span>${esc(t()[p])}</a>`).join('')}
function progressCount(n){return state.learned.filter(k=>k.split(':')[1]===n).length}
function bookshelf(){return `<div class="bookshelf">${LEVELS.map((n,i)=>{const d=count(n),learned=progressCount(n),total=d.vocab+d.grammar+d.kanji;return `<a class="volume" style="--book:${['#314d41','#8a8e69','#a97656','#647b7b','#474f62'][i]}" href="${n.toLowerCase()}.html"><span class="volume-no">VOL. 0${i+1}</span><strong>${n}</strong><span class="jp-mark" aria-hidden="true">${['芽','葉','花','樹','森'][i]}</span><span class="volume-title">${esc(t().levelnames[i])}</span><span class="volume-counts">${(d.vocab-(d.extra_vocab||0)).toLocaleString()} ${esc(t().vocab)}<br>${d.grammar} ${esc(t().grammar)} · ${d.kanji} ${esc(t().kanji)}${d.extra_vocab?`<br>+ ${d.extra_vocab.toLocaleString()} ${esc(t().extra)}`:''}</span><span class="volume-arrow" aria-hidden="true">↗</span><div class="volume-progress" aria-label="${learned} ${esc(t().learned)}"><i style="width:${Math.min(100,total?learned/total*100:0)}%"></i></div></a>`}).join('')}</div>`}
function home(){const rows=db[state.level].vocab,w=rows[new Date().getDate()%rows.length];$('#main').innerHTML=`<section class="hero"><div class="hero-copy"><span class="eyebrow">${t().eyebrow}</span><h1>${t().hero}</h1><p>${t().intro}</p><a class="primary" href="${state.level.toLowerCase()}.html">${t().start}<span aria-hidden="true">↗</span></a><span class="hero-caption">N5 — N1 &nbsp; · &nbsp; বাংলা + ENGLISH</span></div><div class="book-scene" aria-hidden="true"><div class="scene-orbit"></div><span class="floating-note">your next chapter ↘</span><div class="book-model"><div class="book-cover"><span class="book-volume">THE JAPANESE COLLECTION</span><div class="book-kanji">学</div><strong>Nihongo Path</strong><small>ONE PAGE AT A TIME</small><span class="bookmark-ribbon"></span></div></div><span class="scene-label">A LITTLE, EVERY DAY.</span></div></section><div class="section-head"><h2>${t().choose}</h2><small>${t().shelf}</small></div>${bookshelf()}<div class="two-col"><section class="paper-card daily"><div><span class="eyebrow">${t().today}</span><div class="daily-jp" lang="ja">${esc(title(w))}</div><span class="reading">${esc(w.reading)}</span><p>${esc(meaning(w,'vocab'))}</p>${badge(w,'meaning','vocab')}</div><button class="round-listen" id="dailyListen" aria-label="${t().listen}">▷</button></section><section class="paper-card"><span class="eyebrow">${t().yourProgress}</span><div class="stat-row"><div><strong>${state.learned.length}</strong><small>${t().learned}</small></div><div><strong>${state.saved.length}</strong><small>${t().saved}</small></div></div><a class="quiet-link" href="progress.html">${t().viewProgress} ↗</a></section></div><p class="notice" style="margin-top:26px">${t().quality}</p>`;$('#dailyListen').onclick=e=>speak(title(w),e.currentTarget)}
function catalog(){$('#main').innerHTML=`<span class="eyebrow">${t().shelf}</span><h1>${t().choose}</h1><p class="muted">${t().chapterIntro}</p><p class="notice">${t().quality}</p><div style="margin-top:35px">${bookshelf()}</div>`}
function selectedEntries(){return db[state.level][kind].filter(e=>{const k=entryKey(e);return(filter==='all'||filter==='core'&&e.curriculum_status!=='supplementary'||filter==='extra'&&e.curriculum_status==='supplementary'||filter==='saved'&&state.saved.includes(k)||filter==='learned'&&state.learned.includes(k))&&(!query||[title(e),e.reading,e.romaji,e.other_forms?.join(' '),english(e),meaning(e)].join(' ').toLowerCase().includes(query.toLowerCase()))})}
function results(){const rows=selectedEntries();$('#results').innerHTML=`<div class="results-caption"><span>${rows.length.toLocaleString()} ${t().found}</span><span>${state.level} / ${t()[kind]}</span></div><div class="entry-grid">${rows.slice(0,limit).map((e,i)=>`<button class="entry" data-entry="${esc(e.id)}"><span class="entry-index">${String(i+1).padStart(3,'0')}</span><span class="entry-state">${state.saved.includes(entryKey(e))?'★':''} ${state.learned.includes(entryKey(e))?'✓':''}</span><strong class="entry-word" lang="ja">${esc(title(e))}</strong><span class="entry-reading">${esc(e.reading||e.romaji)}</span><p class="entry-meaning">${esc(meaning(e))}</p>${badge(e)}${e.curriculum_status==='supplementary'?`<span class="review-status">${t().extra}</span>`:''}</button>`).join('')}</div>${!rows.length?`<p class="empty">${t().empty}</p>`:''}${rows.length>limit?`<button id="moreLessons" class="chip load-more">${t().more} &nbsp; ↓</button>`:''}`;$$('[data-entry]').forEach(b=>b.onclick=()=>openEntry(rows.find(e=>e.id===b.dataset.entry)));if($('#moreLessons'))$('#moreLessons').onclick=()=>{limit+=30;results()}}
function level(){const d=db[state.level],i=LEVELS.indexOf(state.level);$('#main').innerHTML=`<a class="back-link" href="lessons.html">← ${t().allLevels}</a><section class="chapter-header"><div><span class="eyebrow">${t().chapter} 0${i+1} / THE JAPANESE COLLECTION</span><h1>${state.level} · ${t().levelnames[i]}</h1><p class="muted">${t().chapterIntro}</p></div><span class="chapter-number" aria-hidden="true">0${i+1}</span></section><nav class="subject-tabs" aria-label="Lesson subjects">${KINDS.map(k=>`<a class="subject ${kind===k?'active':''}" href="${state.level.toLowerCase()}.html?section=${k}" ${kind===k?'aria-current="page"':''}>${t()[k]}<small>${d[k].length.toLocaleString()}</small></a>`).join('')}</nav><p class="notice">${t().quality}</p>${kind==='vocab'&&count(state.level).extra_vocab?`<p class="notice">${t().extraNote}</p>`:''}<div class="toolbar"><div class="search-wrap"><span aria-hidden="true">⌕</span><input type="search" id="search" aria-label="${t().searchLabel}" placeholder="${t().search}" value="${esc(query)}"></div></div><div class="filters">${['all',...(kind==='vocab'&&count(state.level).extra_vocab?['core','extra']:[]),'saved','learned'].map(f=>`<button class="chip ${filter===f?'active':''}" data-filter="${f}" aria-pressed="${filter===f}">${t()[f]}</button>`).join('')}</div><div id="results"></div>`;$('#search').oninput=e=>{query=e.target.value;limit=30;results()};$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;limit=30;level()});results();document.title=`${state.level} ${t()[kind]} · Nihongo Path Books`}
function speak(text,button){if(window.NihongoSpeech)window.NihongoSpeech.play(text,button);else{const p=document.createElement('p');p.className='speech-status';p.textContent=state.lang==='bn'?'অডিও এখন পাওয়া যাচ্ছে না।':'Audio is currently unavailable.';button.after(p)}}
function openEntry(e){current=e;const k=entryKey(e),l=local(e),formation=fieldText(e,'formation'),guidance=fieldText(e,'guidance');$('#detailBody').innerHTML=`<article class="lesson-book"><section class="lesson-summary"><span class="eyebrow">${e.level} / ${t()[kind]}</span><h1 id="detailTitle" lang="ja">${esc(title(e))}</h1><p class="muted">${esc(e.reading||e.romaji)}</p><h2>${esc(meaning(e))}</h2>${badge(e)}${state.lang==='bn'&&checked(e,'meaning')?`<p class="source-gloss">${esc(english(e))}</p>`:''}${e.curriculum_status==='supplementary'?`<p class="notice" style="margin-top:20px">${t().extraNote}</p>`:''}<div class="lesson-actions"><button class="chip" id="listen">▷ ${t().listen}</button><button class="chip" id="save">${state.saved.includes(k)?'★ '+t().savedAction:'☆ '+t().save}</button><button class="chip" id="learned">${state.learned.includes(k)?'✓ '+t().marked:t().mark}</button></div>${kind==='kanji'?`<div class="kanji-readings" style="margin-top:25px"><b>${t().onyomi}</b><br><span lang="ja">${esc(e.onyomi?.join('、')||'—')}</span><br><b>${t().kunyomi}</b><br><span lang="ja">${esc(e.kunyomi?.join('、')||'—')}</span><p class="muted">${e.strokes||0} ${t().strokes}</p></div>`:''}</section><section class="lesson-content">${formation?`<h3>${t().formation}</h3><div class="formation">${esc(formation)}</div>${badge(e,'formation')}`:''}${guidance?`<h3 style="margin-top:25px">${t().guidance}</h3><p class="guidance">${esc(guidance)}</p>${badge(e,'guidance')}`:''}${e.examples?.length?`<h3 style="margin-top:30px">${t().examples}</h3>${e.examples.map((x,i)=>`<section class="example"><div class="example-number">${String(i+1).padStart(2,'0')}</div><p class="ja" lang="ja">${esc(x.ja)}</p>${state.lang==='bn'&&checked(e,'examples.'+i)?`<p class="translation">${esc(l.examples?.[i])}</p>`:''}<p class="en">${esc(x.en)}</p>${badge(e,'examples.'+i)}</section>`).join('')}`:kind==='kanji'?`<h3>${t().words}</h3><p lang="ja" class="guidance">${esc(e.words?.join(' · ')||title(e))}</p>`:''}${!formation&&!guidance&&!e.examples?.length&&kind!=='kanji'?`<p class="notice">${t().quality}</p>`:''}</section></article>`;$('#listen').onclick=x=>speak(title(e),x.currentTarget);for(const [id,list]of[['save','saved'],['learned','learned']])$('#'+id).onclick=()=>{state[list]=state[list].includes(k)?state[list].filter(x=>x!==k):[...state[list],k];persist();openEntry(e)};if(!$('#detail').open)$('#detail').showModal()}
function practice(){const all=db[state.level].vocab,saved=all.filter(e=>state.saved.includes(entryKey(e,'vocab'))),list=saved.length?saved:all,e=list[cardIndex%list.length];if(!e){$('#main').innerHTML=`<p class="empty">${t().reviewNone}</p>`;return}$('#main').innerHTML=`<span class="eyebrow">A DAILY RITUAL</span><h1>${t().review}</h1><p class="muted">${t().practiceIntro}</p><div class="practice-toolbar"><button id="flashMode" class="chip ${mode==='flash'?'active':''}">${t().flash}</button><button id="quizMode" class="chip ${mode==='quiz'?'active':''}">${t().quiz}</button><select id="practiceLevel" aria-label="${t().level}">${LEVELS.map(n=>`<option ${state.level===n?'selected':''}>${n}</option>`).join('')}</select></div><section class="practice-card"><span class="eyebrow">${t().card} ${String(cardIndex%list.length+1).padStart(3,'0')} / ${list.length}</span><div class="practice-word" lang="ja">${esc(title(e))}</div><p class="muted">${esc(e.reading)}</p>${mode==='flash'?`<div class="practice-answer">${flipped?esc(meaning(e,'vocab')):'—'}</div>${flipped?badge(e,'meaning','vocab'):''}<div><button id="flipCard" class="primary">${flipped?t().next:t().reveal} <span>↗</span></button></div>`:`<div id="answers" class="answer-grid"></div><p id="feedback" class="practice-feedback" role="status"></p><button id="nextQuestion" class="primary" hidden>${t().next} ↗</button>`}</section><p class="practice-note">${t().practiceNote}</p>`;$('#flashMode').onclick=()=>{mode='flash';flipped=false;practice()};$('#quizMode').onclick=()=>{mode='quiz';practice()};$('#practiceLevel').onchange=async ev=>{const n=ev.target.value;ev.target.disabled=true;try{await loadLevel(n);state.level=n;cardIndex=0;flipped=false;persist();practice()}catch{showLoadError()}};if(mode==='flash')$('#flipCard').onclick=()=>{if(flipped)cardIndex++;flipped=!flipped;practice()};else{answered=false;const used=new Set([meaning(e,'vocab')]);const candidates=shuffle(all.filter(x=>x.id!==e.id));const opts=[e];for(const x of candidates){const m=meaning(x,'vocab');if(!used.has(m)){used.add(m);opts.push(x)}if(opts.length===4)break}shuffle(opts);$('#answers').innerHTML=opts.map((x,i)=>`<button class="answer" data-answer="${i}">${esc(meaning(x,'vocab'))}</button>`).join('');$$('[data-answer]').forEach(b=>b.onclick=()=>{if(answered)return;answered=true;const ok=opts[+b.dataset.answer].id===e.id;$$('[data-answer]').forEach(a=>{a.disabled=true;if(opts[+a.dataset.answer].id===e.id)a.classList.add('correct')});if(!ok)b.classList.add('incorrect');$('#feedback').textContent=ok?t().right:t().wrong+': '+meaning(e,'vocab');$('#nextQuestion').hidden=false});$('#nextQuestion').onclick=()=>{cardIndex++;practice()}}}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function progress(){$('#main').innerHTML=`<span class="eyebrow">${t().overview}</span><h1>${t().yourProgress}</h1><p class="muted">${t().progressIntro}</p><div class="two-col"><section class="paper-card"><div class="stat-row"><div><strong>${state.learned.length}</strong><small>${t().learned}</small></div><div><strong>${state.saved.length}</strong><small>${t().saved}</small></div></div></section><section class="paper-card"><span class="eyebrow">${t().updated}</span><p class="notice" style="margin-top:15px">${t().local}</p><div class="filters"><button class="chip" id="exportProgress">↓ ${t().export}</button><button class="chip" id="importProgress">↑ ${t().import}</button><input type="file" id="progressFile" accept="application/json,.json" hidden></div><p id="importStatus" role="status"></p></section></div><div class="progress-list">${LEVELS.map((n,i)=>{const d=count(n),total=d.vocab+d.grammar+d.kanji,done=progressCount(n);return `<section class="progress-item"><strong>${n}</strong><div><span>${t().levelnames[i]}</span><small class="muted" style="display:block">${done.toLocaleString()} / ${total.toLocaleString()} ${t().learned}</small><div class="progress-track"><i style="width:${Math.min(100,done/total*100)}%"></i></div></div><a class="quiet-link" href="${n.toLowerCase()}.html">${t().read} ↗</a></section>`}).join('')}</div>`;$('#exportProgress').onclick=()=>{const blob=new Blob([JSON.stringify({format:'nihongo-path-progress-v1',exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='nihongo-path-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#importStatus').textContent=t().downloaded};$('#importProgress').onclick=()=>$('#progressFile').click();$('#progressFile').onchange=async ev=>{try{const f=ev.target.files[0];if(!f)return;if(f.size>5000000)throw Error();const parsed=JSON.parse(await f.text()),s=parsed.state||parsed;if(!s||!Array.isArray(s.saved)||!Array.isArray(s.learned)||![...s.saved,...s.learned].every(x=>typeof x==='string'&&/^(vocab|grammar|kanji):N[1-5]:.+$/.test(x)))throw Error();state.saved=[...new Set([...state.saved,...s.saved])];state.learned=[...new Set([...state.learned,...s.learned])];persist();progress();$('#importStatus').textContent=t().imported}catch{$('#importStatus').textContent=t().invalid}}}
function sources(){const totals=KINDS.map(k=>`${Object.values(index).reduce((n,d)=>n+d[k],0).toLocaleString()} ${t()[k]}`).join(' · ');$('#main').innerHTML=`<article class="sources-content"><span class="eyebrow">SOURCE NOTES / COLOPHON</span><h1>${t().sources}</h1><p>${t().sourceIntro}</p><p><strong>${totals}</strong></p><h2>${t().reviewTitle}</h2><p>${t().reviewText}</p><p><a href="data/review-progress.json">Review progress</a> · <a href="data/review-status.json">Field-level review status</a></p><h2>${t().attribution}</h2><p>${t().sourceList}</p><ul><li><a href="https://github.com/evanclan/OpenJLPT">OpenJLPT</a> · <a href="data/NOTICE.md">Attribution</a> · <a href="data/LICENSE">CC BY-SA 4.0</a></li><li><a href="https://github.com/jkindrix/japanese-language-data">Japanese Language Data</a> · <a href="data/SUPPLEMENT-ATTRIBUTION.md">Supplement attribution</a></li><li><a href="https://hanabira.org">Hanabira</a> · <a href="data/HANABIRA-ATTRIBUTION.md">Attribution</a></li><li><a href="data/audit.json">${t().dataAudit}</a> · <a href="data/coverage.json">Coverage</a> · <a href="data/reference-audit.json">Reference inventory</a></li></ul><p>${t().extraNote}</p><h2>Design & animation</h2><p>Independent book-inspired interface. Theme transition inspiration: <a href="https://skiper-ui.com/v1/skiper26">Skiper UI — Theme Toggle #26</a>. The interaction uses the browser View Transition API, with a reduced-motion fallback. No paid Skiper components are included.</p><p>${t().local}</p></article>`}
function render(){document.documentElement.lang=state.lang;paintTheme();$('#language').value=state.lang;$('#theme').setAttribute('aria-label',t().theme);$('#closeDetail').setAttribute('aria-label',t().close);nav();window.updateAdLabel?.(state.lang);({home,lessons:catalog,level,review:practice,progress,sources}[page]||home)();if(page!=='level')document.title=`${t()[page]||'Nihongo Path'} · Nihongo Path Books`}
async function loadLevel(n){if(db[n])return;const res=await fetch(`data/${n.toLowerCase()}.json?v=${VERSION}`);if(!res.ok)throw Error(n);const data=await res.json();if(!KINDS.every(k=>Array.isArray(data[k])))throw Error('Invalid curriculum');db[n]=data}
function showLoadError(){$('#main').innerHTML=`<p class="empty">${t().loadError}</p><button id="retryLoad" class="chip">${t().retry}</button>`;$('#retryLoad').onclick=()=>location.reload()}
$('#language').onchange=e=>{state.lang=e.target.value;persist();render();if($('#detail').open&&current)openEntry(current)};
$('#theme').onclick=ev=>{state.dark=!state.dark;persist();const change=()=>paintTheme();if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.style.setProperty('--theme-x',`${ev.clientX||innerWidth-50}px`);document.documentElement.style.setProperty('--theme-y',`${ev.clientY||40}px`);document.startViewTransition(change)}else change()};
$('#closeDetail').onclick=()=>{$('#detail').close();if(page==='level')results()};$('#detail').onclick=ev=>{if(ev.target===$('#detail')){$('#detail').close();if(page==='level')results()}};$('#detail').addEventListener('close',()=>{if(page==='level')results()});
paintTheme();$('#main').innerHTML=`<div class="loading">${t().loading}</div>`;
(async()=>{const [response,status]=await Promise.all([fetch(`data/index.json?v=${VERSION}`),fetch(`data/review-status.json?v=${VERSION}`).then(r=>r.ok?r.json():{}).catch(()=>({}))]);if(!response.ok)throw Error('Index unavailable');index=await response.json();reviewed=status;for(const n of LEVELS)if(!index[n])throw Error('Incomplete index');if(['home','level','review'].includes(page))await loadLevel(state.level);render()})().catch(showLoadError);
